import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { publicAPI } from '../../services/api';
import Card from '../../components/Card';
import Loader from '../../components/Loader';
import EmptyState from '../../components/EmptyState';
import Button from '../../components/Button';

const CATEGORIES = ['ALL', 'WASTE_SEGREGATION', 'THREE_R', 'SUSTAINABILITY'];

const BlogCard = ({ blog }) => (
  <Link to={`/blogs/${blog.slug}`} style={{ textDecoration: 'none' }}>
    <Card hover>
      <Card.Body>
        <span className="badge badge--neutral" style={{ marginBottom: 'var(--space-3)', textTransform: 'uppercase', letterSpacing: '0.4px', color: 'var(--eco-primary)' }}>
          {blog.category?.replace('_', ' ')}
        </span>
        <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 'var(--text-md)', fontWeight: 700, color: 'var(--eco-text)', marginBottom: 'var(--space-2)', lineHeight: 1.3 }}>
          {blog.title}
        </h3>
        <p style={{ fontSize: 'var(--text-sm)', color: 'var(--eco-text-secondary)', lineHeight: 1.6, marginBottom: 'var(--space-4)' }}>
          {blog.content?.slice(0, 120)}...
        </p>
        <div className="flex-between" style={{ fontSize: 'var(--text-xs)', color: 'var(--eco-text-muted)' }}>
          <span>✍️ {blog.author}</span>
          <span>{new Date(blog.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
        </div>
      </Card.Body>
    </Card>
  </Link>
);

const BlogsPage = () => {
  const [blogs, setBlogs]           = useState([]);
  const [loading, setLoading]       = useState(true);
  const [error, setError]           = useState('');
  const [page, setPage]             = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [category, setCategory]     = useState('ALL');

  useEffect(() => {
    setLoading(true);
    const cat = category === 'ALL' ? '' : category;
    publicAPI.getBlogs(page, 9, cat)
      .then(res => { setBlogs(res.data.content); setTotalPages(res.data.totalPages); })
      .catch(() => setError('Failed to load blogs.'))
      .finally(() => setLoading(false));
  }, [page, category]);

  return (
    <div style={{ background: 'var(--eco-bg)', minHeight: '100vh' }}>
      <div className="section-header">
        <h1 className="section-header__title">📰 Awareness Blog</h1>
        <p className="section-header__subtitle">Tips, guides, and insights on sustainable living.</p>
      </div>

      <div className="container" style={{ padding: 'var(--space-10) var(--space-6)' }}>
        {/* Category Filters */}
        <div className="flex gap-2 mb-8" style={{ flexWrap: 'wrap' }}>
          {CATEGORIES.map(c => (
            <button key={c}
              onClick={() => { setCategory(c); setPage(0); }}
              className={`btn btn--sm ${category === c ? 'btn--primary' : 'btn--ghost'}`}>
              {c === 'ALL' ? 'All' : c.replace('_', ' ')}
            </button>
          ))}
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        {loading ? (
          <Loader text="Loading blogs..." />
        ) : blogs.length === 0 ? (
          <EmptyState icon="📭" title="No blogs yet" subtitle="Check back soon for sustainability tips and guides." />
        ) : (
          <>
            <div className="grid grid--auto">
              {blogs.map(b => <BlogCard key={b.id} blog={b} />)}
            </div>

            {totalPages > 1 && (
              <div className="flex-center gap-2 mt-8">
                <Button variant="secondary" size="sm" disabled={page === 0} onClick={() => setPage(p => Math.max(0, p - 1))}>← Prev</Button>
                {Array.from({ length: totalPages }, (_, i) => (
                  <button key={i} onClick={() => setPage(i)}
                    className={`btn btn--sm ${page === i ? 'btn--primary' : 'btn--ghost'}`}>{i + 1}</button>
                ))}
                <Button variant="secondary" size="sm" disabled={page >= totalPages - 1} onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}>Next →</Button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default BlogsPage;
